<?php
namespace App\Repositories; use App\Core\Database;
final class ProjectRepository extends BaseRepository{protected string $table='projects';public function all(int $limit=500):array{$s=Database::pdo()->query('SELECT p.*,c.full_name,COALESCE(s.name,"") service_name FROM projects p JOIN clients c ON c.id=p.client_id LEFT JOIN services s ON s.id=p.service_id ORDER BY p.start_date DESC,p.id DESC LIMIT '.max(1,min(1000,$limit)));return $s->fetchAll();}public function findWithWorkflow(int $id):?array{$r=$this->find($id);if(!$r)return null;$pdo=Database::pdo();$s=$pdo->prepare('SELECT * FROM workflow_instances WHERE project_id=? ORDER BY id DESC LIMIT 1');$s->execute([$id]);$r['workflow']=$s->fetch()?:null;$r['steps']=[];if($r['workflow']){$s=$pdo->prepare('SELECT wsi.*,ws.title,ws.step_type,ws.requirement FROM workflow_step_instances wsi JOIN workflow_steps ws ON ws.id=wsi.workflow_step_id WHERE wsi.workflow_instance_id=? ORDER BY ws.sort_order');$s->execute([$r['workflow']['id']]);$r['steps']=$s->fetchAll();}return $r;}}
